    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
